import{_ as l,o as i,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Hammer (Day 1) - Calamari API Roadmap","description":"","frontmatter":{"title":"CDS Hammer (Day 1) - Calamari API Roadmap","date":"2014-10-29T00:00:00.000Z","updated":"2014-10-30T00:00:00.000Z","tags":["Ceph","Calamari API","RESTful API","OpenStack","Community Involvement"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_1_-_Calamari_API_Roadmap.md","filePath":"posts/2014/CDS_Hammer_Day_1_-_Calamari_API_Roadmap.md","lastUpdated":1780459816000}'),e={name:"posts/2014/CDS_Hammer_Day_1_-_Calamari_API_Roadmap.md"};function o(m,a,p,s,_,n){return i(),r("div",null,[...a[0]||(a[0]=[t("<p>本次会议详细讨论了 Calamari API 的现状、目标和未来发展方向。以下是对会议内容的总结：</p><p><strong>Calamari API 概述</strong></p><ul><li><strong>Calamari 重新定义</strong>： 将 Calamari 定位为后端服务层和 API 层，去除图形用户界面（GUI），聚焦于 API 本身及其功能。</li><li><strong>Calamari 目标</strong>： 实现与 Rados、RBD 和 RGW 命令行工具的功能对等，提供一致的 RESTful 接口，并支持异步操作。</li><li><strong>Calamari 优势</strong>： 提供一致的 RESTful 接口，方便开发者使用；支持异步操作，提高用户体验；与其他 Ceph 管理、监控工具兼容。</li></ul><p><strong>Calamari 目标用户</strong></p><ul><li>Ceph 社区成员</li><li>Red Hat 社区成员</li><li>开源社区项目</li><li>OpenStack 等云平台</li></ul><p><strong>Calamari 当前状态</strong></p><ul><li>已实现约 30 个 Rados 命令的功能。</li><li>已覆盖 OSD 和 Pool 相关功能。</li><li>对 Mon 和 Metadata Server 的支持较少。</li></ul><p><strong>Calamari 1.3 版本计划</strong></p><ul><li>改进 Crush 支持功能，包括管理节点和规则。</li><li>在 GUI 中展示多集群功能。</li><li>引入基于角色的授权机制。</li></ul><p><strong>社区参与机会</strong></p><ul><li>贡献文档</li><li>报告新功能需求</li><li>参与邮件列表讨论</li><li>开发和打包 Calamari</li><li>贡献代码</li></ul><p><strong>行动计划</strong></p><ul><li>完成Calamari 1.3 版本开发。</li><li>推动Calamari 在更多发行版中打包。</li><li>加强社区参与和沟通。</li></ul><p><strong>其他</strong></p><ul><li>讨论了与其他 Ceph 管理、监控工具的兼容性。</li><li>讨论了 Calamari GUI 的命名问题。</li><li>讨论了 Calamari 依赖包的打包问题。</li></ul><p>本次会议对 Calamari API 的现状、目标和未来计划进行了详细的讨论，并明确了社区参与的机会。Calamari 作为 Ceph 的一个重要管理工具，将在 Ceph 社区中发挥越来越重要的作用。</p>",16)])])}const u=l(e,[["render",o]]);export{d as __pageData,u as default};
